using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        PlayerMovement pm = GameObject.FindFirstObjectByType<PlayerMovement>();
        if (pm == null)
        {
            result.LogError("No PlayerMovement found in scene.");
            return;
        }

        GameObject player = pm.gameObject;
        CharacterController cc = player.GetComponent<CharacterController>();

        result.Log("Player: {0}, position: {1}", player, player.transform.position);
        if (cc != null)
        {
            result.Log("CharacterController center: {0}, height: {1}, radius: {2}", cc.center, cc.height, cc.radius);
        }
        else
        {
            result.LogWarning("No CharacterController found.");
        }

        Renderer[] renderers = player.GetComponentsInChildren<Renderer>();
        if (renderers.Length > 0)
        {
            Bounds bounds = renderers[0].bounds;
            foreach (Renderer r in renderers)
            {
                bounds.Encapsulate(r.bounds);
            }
            result.Log("Combined renderer bounds: center={0}, size={1}", bounds.center, bounds.size);
            result.Log("Local center offset from transform: {0}", bounds.center - player.transform.position);
        }
        else
        {
            result.LogWarning("No Renderer found under player.");
        }

        CameraFollow cf = GameObject.FindFirstObjectByType<CameraFollow>();
        if (cf != null)
        {
            result.Log("CameraFollow found on: {0}", cf.gameObject);
        }
    }
}

